import React, { useState, useEffect } from 'react';
import { Link, useParams, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { casesAPI, openingsAPI } from '../services/api';
import ImageWithFallback from '../components/ImageWithFallback';

const CaseDetailPage = () => {
  const { balance } = useAuth();
  const { caseId } = useParams();
  const navigate = useNavigate();

  const [caseData, setCaseData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchCaseDetails = async () => {
      try {
        const response = await casesAPI.getCaseById(caseId);
        setCaseData(response.data);
      } catch (err) {
        setError('Failed to load case details');
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    if (caseId) {
      fetchCaseDetails();
    }
  }, [caseId]);

  const handleOpenCase = async (count) => {
    try {
      // In a real app, we'd show an exciting animation here
      const response = await openingsAPI.openCase(caseId);

      // The opening response returns the awarded item id, not an embedded item object.
      alert(`Congratulations! You won item #${response.data.item_id}!`);

      // Optionally navigate to inventory or show celebration
      navigate(`/inventory`);
    } catch (err) {
      setError('Failed to open case: ' + (err.response?.data?.detail || err.message || 'Request failed'));
      console.error(err);
    }
  };

  if (loading) {
    return (
      <div className="container">
        <div className="row justify-content-center">
          <div className="col-md-4">
            <div className="text-center py-5">
              <div className="spinner-border text-primary" role="status">
                <span className="visually-hidden">Loading...</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="container">
        <div className="row justify-content-center">
          <div className="col-md-6">
            <div className="alert alert-danger">
              {error}
            </div>
            <Link className="btn btn-outline-primary" to="/cases">
              ← Back to Cases
            </Link>
          </div>
        </div>
      </div>
    );
  }

  if (!caseData) {
    return (
      <div className="container">
        <div className="row justify-content-center">
          <div className="col-md-4">
            <div className="text-center py-5">
              <h3>Case not found</h3>
              <Link className="btn btn-outline-primary" to="/cases">
                ← Back to Cases
              </Link>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container">
      <div className="row mb-4">
        <div className="col-md-8">
          <h1 className="gradient-text">{caseData.name}</h1>
          <p className="lead">{caseData.description || 'A mysterious case with valuable rewards'}</p>
        </div>
        <div className="col-md-4 text-end">
          <div className="d-flex flex-column align-items-end">
            <span className="badge bg-primary fs-5 mb-2">{caseData.price.toLocaleString()} €</span>
            <h2>Balance: <span className="text-success">{balance.toLocaleString()} €</span></h2>
          </div>
        </div>
      </div>

      {/* Case Image */}
      <div className="text-center mb-5">
        <ImageWithFallback
          src={caseData.image_url}
          alt={caseData.name}
          className="case-detail-image img-fluid"
          style={{ maxWidth: '300px', maxHeight: '300px', borderRadius: '16px' }}
        />
      </div>

      {/* Case Contents */}
      <div className="row mb-5">
        <div className="col-12">
          <div className="card">
            <div className="card-header">
              <h5 className="mb-0">Case Contents</h5>
            </div>
            <div className="card-body">
              {/* In a real app, we'd fetch and display the actual items with probabilities */}
              <div className="row g-4">
                {/* Example items - would come from API */}
                {[1, 2, 3, 4, 5].map((item, index) => (
                  <div key={index} className="col-md-3 col-sm-6">
                    <div className="card-item text-center p-3 border rounded">
                      <div className="item-icon mb-3">
                        <ImageWithFallback
                             src={null}
                             alt="Item"
                             className="img-fluid"
                             style={{ width: '60px', height: '60px' }}
                        />
                      </div>
                      <div className="item-name fw-medium">AK-47 | Redline</div>
                      <div className="item-rarity badge bg-classified mt-2">Classified</div>
                      <div className="item-probability text-muted small">0.5%</div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Open Options */}
      <div className="row g-4 mb-5">
        <div className="col-12">
          <h4>Open Options</h4>
          <div className="btn-group w-100" role="group" aria-label="Case opening options">
            {[1, 2, 3, 5, 10].map(count => (
              <Link 
                key={count} 
                to="#" 
                className={`btn btn-outline-primary flex-fill ${count === 1 ? 'active' : ''}`}
                onClick={(e) => { e.preventDefault(); handleOpenCase(count); }}
              >
                x{count}
              </Link>
            ))}
          </div>
        </div>
      </div>

      {/* Warning */}
      <div className="alert alert-info">
        <i className="bi bi-info-circle me-2"></i>
        Virtual currency — no real-money value
      </div>
    </div>
  );
};

export default CaseDetailPage;
